async function main(req) {
  const baseUrl = env('UPSTREAM_URL', 'https://jsonplaceholder.typicode.com');
  const body = jsonParse(req.body, {});
  const resource = body.resource || 'posts';
  const id = body.id || '';

  const url = id ? `${baseUrl}/${resource}/${id}` : `${baseUrl}/${resource}?_limit=5`;
  log('fetching:', url);

  try {
    const resp = await fetch(url);
    const data = await resp.json();
    return {
      source: url,
      status: resp.status,
      data: data
    };
  } catch (err) {
    return { error: err.message, url };
  }
}
